create role authenticator login noinherit;
create role anon nologin;
create role authenticated nologin;
grant anon, authenticated to authenticator;

create table perfiles (id uuid primary key, alias text, puntos int);

create function mi_id() returns uuid language sql stable as
$$ select nullif(current_setting('request.jwt.claims', true)::json->>'sub','')::uuid $$;

alter table perfiles enable row level security;
create policy ver_lo_mio on perfiles for select to authenticated using (id = mi_id());
grant select on perfiles to authenticated;

