// Factura mensual de Supabase Pro con los precios de lista leídos el 16-11-2026 (USD; ver supabase.com/pricing).
const PRO = { base: 25, credito: 10, discoGB: 8, discoExtra: 0.125, egresoGB: 250, egresoExtra: 0.09,
              mau: 100000, mauExtra: 0.00325, inv: 2e6, invExtraPorMillon: 2 };
const COMPUTO = { Micro: 10, Small: 15, Medium: 60, Large: 110 };   // USD por mes, página de cómputo
function factura({ discoGB, egresoGB, mau, invocaciones, tam = "Micro" }) {
  const l = [];
  l.push(["Plan Pro", PRO.base]);
  l.push([`Cómputo ${tam} menos crédito`, Math.max(COMPUTO[tam] - PRO.credito, 0)]);
  l.push(["Disco extra", Math.max(discoGB - PRO.discoGB, 0) * PRO.discoExtra]);
  l.push(["Egreso extra", Math.max(egresoGB - PRO.egresoGB, 0) * PRO.egresoExtra]);
  l.push(["Usuarios activos extra", Math.max(mau - PRO.mau, 0) * PRO.mauExtra]);
  l.push(["Invocaciones extra", Math.max(invocaciones - PRO.inv, 0) / 1e6 * PRO.invExtraPorMillon]);
  return l;
}
function mostrar(nombre, e) {
  const l = factura(e); const t = l.reduce((a, [, v]) => a + v, 0);
  console.log(nombre); l.filter(([, v]) => v > 0).forEach(([k, v]) => console.log("  " + k.padEnd(30), v.toFixed(2).padStart(8)));
  console.log("  " + "TOTAL".padEnd(30), t.toFixed(2).padStart(8));
}
mostrar("A. Chica: 3 GB de disco, 40 GB de egreso, 8.000 usuarios", { discoGB: 3, egresoGB: 40, mau: 8000, invocaciones: 50000 });
mostrar("B. Mediana: 20 GB, 400 GB, 150.000 usuarios, Small", { discoGB: 20, egresoGB: 400, mau: 150000, invocaciones: 3e6, tam: "Small" });

// Medidor de lecturas de Firestore (juguete): aplica algunas reglas de conteo de la página oficial de precios (leída el 16-11-2026).
// No cuenta las entradas de índice: en consultas con un solo campo de rango no se cobran.
const GRATIS_DIA = 50000;
function lecturas({ devueltos, saltados = 0, getsEnReglas = 0 }) {
  let n = devueltos;
  n += saltados;                 // cada documento salteado con offset se cobra
  n += getsEnReglas;             // get() / exists() en las reglas: una lectura extra por documento dependiente
  return Math.max(n, 1);         // mínimo una lectura por consulta, aunque no devuelva nada
}
const casos = [
  ["Lista de 100 documentos", { devueltos: 100 }],
  ["Consulta sin resultados", { devueltos: 0 }],
  ["Página 46 con offset (20 por página)", { devueltos: 20, saltados: 900 }],
  ["Misma página con cursor", { devueltos: 20 }],
  ["100 documentos con un get() en la regla", { devueltos: 100, getsEnReglas: 1 }],
];
for (const [nombre, c] of casos) {
  const l = lecturas(c);
  console.log(nombre.padEnd(46), String(l).padStart(5), "lecturas ->", Math.floor(GRATIS_DIA / l), "aperturas/día en la cuota gratis");
}
// Un oyente: lectura inicial + una por cada documento que cambia
const oyente = 100 + 10 * 6;
console.log("Oyente sobre 100 docs, 10 cambian 6 veces:", oyente, "lecturas");
